def open_slk(self, data):
    """
    Open a SLK file, which may contain XLM/Excel 4 macros
    :param data: file contents in a bytes string
    :return: nothing
    """
    # TODO: Those results should be stored as XLM macros, not VBA
    log.info('Opening SLK file %s' % self.filename)
    xlm_macro_found = False
    xlm_macros = []
    xlm_macros.append('Formulas and XLM/Excel 4 macros extracted from SLK file:')
    for line in data.splitlines(keepends=False):
        if line.startswith(b'O'):
            # Option: "O;E" indicates a macro sheet, must appear before NN and C rows
            for s in line.split(b';'):
                if s.startswith(b'E'):
                    xlm_macro_found = True
                    log.debug('SLK parser: found macro sheet')
        elif line.startswith(b'NN') and xlm_macro_found:
            # Name that can trigger a macro, for example "Auto_Open"
            for s in line.split(b';'):
                if s.startswith(b'N') and s.strip() != b'NN':
                    xlm_macros.append('Named cell: %s' % bytes2str(s[1:]))
        elif line.startswith(b'C') and xlm_macro_found:
            # Cell
            for s in line.split(b';'):
                if s.startswith(b'E'):
                    xlm_macros.append('Formula or Macro: %s' % bytes2str(s[1:]))
    if xlm_macro_found:
        self.contains_xlm_macros = True
        self.xlm_macros = xlm_macros
    self.type = TYPE_SLK

def detect_xlm_macros(self):
    """
    Detect the potential presence of Excel 4/XLM macros in the file, by checking
    if it contains a macro worksheet. Both OLE and OpenXML files are supported.
    Only Excel files may contain XLM macros, and also SLK and CSV files.

    If XLMMacroDeobfuscator is available, it will be used. Otherwise plugin_biff
    is used as fallback (plugin_biff only supports OLE files, not XLSX or XLSB)

    :return: bool, True if at least one macro worksheet has been found, False otherwise
    """
    log.debug("detect xlm macros")
    # if this method was already called, return the previous result:
    if self.contains_xlm_macros is not None:
        return self.contains_xlm_macros
    # if this is a SLK file, the analysis was done in open_slk:
    if self.type == TYPE_SLK:
        return self.contains_xlm_macros
    # TODO: check also CSV files for formulas?
    self.xlm_macros = []
    # check if the file is Excel, otherwise return False
    if not self.ftg.is_excel():
        self.contains_xlm_macros = False
        return False
    if XLMDEOBFUSCATOR:
        # XLMMacroDeobfuscator is available, use it:
        # But it only works with files on disk for now
        if not self.file_on_disk:
            log.warning('XLMMacroDeobfuscator only works with files on disk, not in memory. Analysis might be less complete.')
        else:
            try:
                return self._extract_xlm_xlmdeobf()
            except Exception:
                log.error('Error when running XLMMacroDeobfuscator')
    # fall back to plugin_biff:
    if self.ole_file is None:
        # TODO: handle OpenXML here
        return False
    return self._extract_xlm_plugin_biff()

def consume(self, stream, props):
    for (name, size) in props:
        if self[name]:
            stream.read(size)

def will_jump_to(self, size):
    self._next_jump = ('jump', (self._pos, size))
    return self

def check_values(self, name, format, size, expected):
    value = self.unpacks(format, size)
    if value != expected:
        self.raise_error('Invalid {0}: expected {1} got {2}'.format(name, str(expected), str(value)))

def consume_GuidAndFont(stream):
    # GuidAndFont: [MS-OFORMS] 2.4.7
    UUIDS = stream.unpacks('<LHH', 8) + stream.unpacks('>Q', 8)
    if UUIDS == (199447043, 36753, 4558, 11376937813817407569):
        # UUID == {0BE35203-8F91-11CE-9DE300AA004BB851}
        # StdFont: [MS-OFORMS] 2.4.12
        stream.check_value('StdFont (version)', '<B', 1, 1)
        # Skip sCharset, bFlags, sWeight, ulHeight
        stream.read(9)
        bFaceLen = stream.unpack('<B', 1)
        stream.read(bFaceLen)
    elif UUIDS == (2948729120, 55886, 4558, 13349514450607572916):
        # UUID == {AFC20920-DA4E-11CE-B94300AA006887B4}
        consume_TextProps(stream)
    else:
        stream.raise_error('Invalid GuidAndFont (UUID)', 16)

def extract_OleFormVariables(ole_file, stream_dir):
    control = ExtendedStream.open(ole_file, '/'.join(stream_dir + ['f']))
    variables = list(consume_FormControl(control))
    data = ExtendedStream.open(ole_file, '/'.join(stream_dir + ['o']))
    for var in variables:
        # See FormEmbeddedActiveXControlCached for type definition: [MS-OFORMS] 2.4.5
        if var['ClsidCacheIndex'] == 7:
            consume_FormControl(data)
        elif var['ClsidCacheIndex'] == 12:
            consume_ImageControl(data)
        elif var['ClsidCacheIndex'] == 14:
            consume_FormControl(data)
        elif var['ClsidCacheIndex'] in [15, 23, 24, 25, 26, 27, 28]:
            var['value'], var['caption'], var['group_name'] = consume_MorphDataControl(data)
        elif var['ClsidCacheIndex'] == 16:
            consume_SpinButtonControl(data)
        elif var['ClsidCacheIndex'] == 17:
            consume_CommandButtonControl(data)
        elif var['ClsidCacheIndex'] == 18:
            consume_TabStripControl(data)
        elif var['ClsidCacheIndex'] == 21:
            var['caption'] = consume_LabelControl(data)
        elif var['ClsidCacheIndex'] == 47:
            consume_ScrollBarControl(data)
        elif var['ClsidCacheIndex'] == 57:
            consume_FormControl(data)
        else:
            # TODO: use logging instead of print
            print('ERROR: Unsupported stored type in user form: {0}'.format(str(var['ClsidCacheIndex'])))
            break
    return variables

def open(cls, ole_file, path):
    stream = ole_file.openstream(path)
    return cls(stream, path)

def _read(self, size):
    self._pos += size
    return self._stream.read(size)

def _pad(self, start, size=4):
    offset = (self._pos - start) % size
    if offset:
        self._read(size - offset)

def read(self, size):
    if self._padding:
        self._pad(self._pad_start, size)
    return self._read(size)

def __exit__(self, exc_type, exc_value, traceback):
    if exc_type is None:
        (jump_type, data) = self._jumps.pop()
        if jump_type == 'jump':
            (start, size) = data
            consummed = self._pos - start
            if consummed > size:
                self.raise_error('Bad jump: too much read ({0} > {1})'.format(consummed, size))
            self.read(size - consummed)
        elif jump_type == 'pad':
            self._pad(data)
        elif jump_type == 'padded':
            (prev_padding, prev_pad_start) = data
            self._pad(self._pad_start)
            self._padding = prev_padding
            self._pad_start = prev_pad_start

def will_pad(self):
    self._next_jump = ('pad', self._pos)
    return self

def consume_FormObjectDepthTypeCount(stream):
   # FormObjectDepthTypeCount: [MS-OFORMS] 2.2.10.7
   (depth, mixed) = stream.unpacks('<BB', 2)
   if mixed & 0x80:
       stream.check_value('FormObjectDepthTypeCount (SITE_TYPE)', '<B', 1, 1)
       return mixed ^ 0x80
   if mixed != 1:
       stream.raise_error('Invalid FormObjectDepthTypeCount (SITE_TYPE): expected 1 got {0}'.format(str(mixed)))
   return 1

def _validate_true_or_false(self, name, val):
    try:
        assert val in (True, False)
    except AssertionError:
        raise Exception("Invalid value for %s!  Must be True or False." % name)

def _validate_int_format(self, name, val):
    if val == "":
        return
    try:
        assert type(val) in (str, unicode)
        assert val.isdigit()
    except AssertionError:
        raise Exception("Invalid value for %s!  Must be an integer format string." % name)

def _validate_function(self, name, val):
    try:
        assert hasattr(val, "__call__")
    except AssertionError:
        raise Exception("Invalid value for %s!  Must be a function." % name)

def _validate_vrules(self, name, val):
    try:
        assert val in (ALL, FRAME, NONE)
    except AssertionError:
        raise Exception("Invalid value for %s!  Must be ALL, FRAME, or NONE." % name)

def _validate_attributes(self, name, val):
    try:
        assert isinstance(val, dict)
    except AssertionError:
        raise Exception("attributes must be a dictionary of name/value pairs!")

