def backslashreplace_errors(exc):
    if isinstance(exc, UnicodeDecodeError):
        u = "".join("\\x{0:02x}".format(c) for c in exc.object[exc.start:exc.end])
        return u, exc.end
    return _backslashreplace_errors(exc)

def is_document_encrypted(self):
