def _get_size(text):
    lines = text.split("\n")
    height = len(lines)
    width = max([_str_block_width(line) for line in lines])
    return (width, height)

def _justify(self, text, width, align):
    excess = width - _str_block_width(text)
    if align == "l":
        return text + excess * " "
    elif align == "r":
        return excess * " " + text
    else:
        if excess % 2:
            # Uneven padding
            # Put more space on right if text is of odd length...
            if _str_block_width(text) % 2:
                return (excess//2)*" " + text + (excess//2 + 1)*" "
            # and more space on left if text is of even length
            else:
                return (excess//2 + 1)*" " + text + (excess//2)*" "
            # Why distribute extra space this way?  To match the behaviour of
            # the inbuilt str.center() method.
        else:
            # Equal padding on either side
            return (excess//2)*" " + text + (excess//2)*" "

def _compute_widths(self, rows, options):
    if options["header"]:
        widths = [_get_size(field)[0] for field in self._field_names]
    else:
        widths = len(self.field_names) * [0]
    for row in rows:
        for index, value in enumerate(row):
            fieldname = self.field_names[index]
            if fieldname in self.max_width:
                widths[index] = max(widths[index], min(_get_size(value)[0], self.max_width[fieldname]))
            else:
                widths[index] = max(widths[index], _get_size(value)[0])
    self._widths = widths

def _get_padding_widths(self, options):

    if options["left_padding_width"] is not None:
        lpad = options["left_padding_width"]
    else:
        lpad = options["padding_width"]
    if options["right_padding_width"] is not None:
        rpad = options["right_padding_width"]
    else:
        rpad = options["padding_width"]
    return lpad, rpad

def _stringify_hrule(self, options):

    if not options["border"]:
        return ""
    lpad, rpad = self._get_padding_widths(options)
    if options['vrules'] in (ALL, FRAME):
        bits = [options["junction_char"]]
    else:
        bits = [options["horizontal_char"]]
    # For tables with no data or fieldnames
    if not self._field_names:
            bits.append(options["junction_char"])
            return "".join(bits)
    for field, width in zip(self._field_names, self._widths):
        if options["fields"] and field not in options["fields"]:
            continue
        bits.append((width+lpad+rpad)*options["horizontal_char"])
        if options['vrules'] == ALL:
            bits.append(options["junction_char"])
        else:
            bits.append(options["horizontal_char"])
    if options["vrules"] == FRAME:
        bits.pop()
        bits.append(options["junction_char"])
    return "".join(bits)

def _stringify_header(self, options):

    bits = []
    lpad, rpad = self._get_padding_widths(options)
    if options["border"]:
        if options["hrules"] in (ALL, FRAME):
            bits.append(self._hrule)
            bits.append("\n")
        if options["vrules"] in (ALL, FRAME):
            bits.append(options["vertical_char"])
        else:
            bits.append(" ")
    # For tables with no data or field names
    if not self._field_names:
        if options["vrules"] in (ALL, FRAME):
            bits.append(options["vertical_char"])
        else:
            bits.append(" ")
    for field, width, in zip(self._field_names, self._widths):
        if options["fields"] and field not in options["fields"]:
            continue
        if self._header_style == "cap":
            fieldname = field.capitalize()
        elif self._header_style == "title":
            fieldname = field.title()
        elif self._header_style == "upper":
            fieldname = field.upper()
        elif self._header_style == "lower":
            fieldname = field.lower()
        else:
            fieldname = field
        bits.append(" " * lpad + self._justify(fieldname, width, self._align[field]) + " " * rpad)
        if options["border"]:
            if options["vrules"] == ALL:
                bits.append(options["vertical_char"])
            else:
                bits.append(" ")
    # If vrules is FRAME, then we just appended a space at the end
    # of the last field, when we really want a vertical character
    if options["border"] and options["vrules"] == FRAME:
        bits.pop()
        bits.append(options["vertical_char"])
    if options["border"] and options["hrules"] != NONE:
        bits.append("\n")
        bits.append(self._hrule)
    return "".join(bits)

def _stringify_row(self, row, options):

    for index, field, value, width, in zip(range(0,len(row)), self._field_names, row, self._widths):
        # Enforce max widths
        lines = value.split("\n")
        new_lines = []
        for line in lines: 
            if _str_block_width(line) > width:
                line = textwrap.fill(line, width)
            new_lines.append(line)
        lines = new_lines
        value = "\n".join(lines)
        row[index] = value

    row_height = 0
    for c in row:
        h = _get_size(c)[1]
        if h > row_height:
            row_height = h

    bits = []
    lpad, rpad = self._get_padding_widths(options)
    for y in range(0, row_height):
        bits.append([])
        if options["border"]:
            if options["vrules"] in (ALL, FRAME):
                bits[y].append(self.vertical_char)
            else:
                bits[y].append(" ")

    for field, value, width, in zip(self._field_names, row, self._widths):

        valign = self._valign[field]
        lines = value.split("\n")
        dHeight = row_height - len(lines)
        if dHeight:
            if valign == "m":
              lines = [""] * int(dHeight / 2) + lines + [""] * (dHeight - int(dHeight / 2))
            elif valign == "b":
              lines = [""] * dHeight + lines
            else:
              lines = lines + [""] * dHeight

        y = 0
        for l in lines:
            if options["fields"] and field not in options["fields"]:
                continue

            bits[y].append(" " * lpad + self._justify(l, width, self._align[field]) + " " * rpad)
            if options["border"]:
                if options["vrules"] == ALL:
                    bits[y].append(self.vertical_char)
                else:
                    bits[y].append(" ")
            y += 1

    # If vrules is FRAME, then we just appended a space at the end
    # of the last field, when we really want a vertical character
    for y in range(0, row_height):
        if options["border"] and options["vrules"] == FRAME:
            bits[y].pop()
            bits[y].append(options["vertical_char"])

    if options["border"] and options["hrules"]== ALL:
        bits[row_height-1].append("\n")
        bits[row_height-1].append(self._hrule)

    for y in range(0, row_height):
        bits[y] = "".join(bits[y])

    return "\n".join(bits)

def _unicode(self, value):
    if not isinstance(value, basestring):
        value = str(value)
    if not isinstance(value, unicode):
        value = unicode(value, self.encoding, "strict")
    return value

def _validate_nonnegative_int(self, name, val):
    try:
        assert int(val) >= 0
    except AssertionError:
        raise Exception("Invalid value for %s: %s!" % (name, self._unicode(val)))

def _set_field_names(self, val):
    val = [self._unicode(x) for x in val]
    self._validate_option("field_names", val)
    if self._field_names:
        old_names = self._field_names[:]
    self._field_names = val
    if self._align and old_names:
        for old_name, new_name in zip(old_names, val):
            self._align[new_name] = self._align[old_name]
        for old_name in old_names:
            if old_name not in self._align:
                self._align.pop(old_name)
    else:
        for field in self._field_names:
            self._align[field] = "c"
    if self._valign and old_names:
        for old_name, new_name in zip(old_names, val):
            self._valign[new_name] = self._valign[old_name]
        for old_name in old_names:
            if old_name not in self._valign:
                self._valign.pop(old_name)
    else:
        for field in self._field_names:
            self._valign[field] = "t"

def _format_value(self, field, value):
    if isinstance(value, int) and field in self._int_format:
        value = self._unicode(("%%%sd" % self._int_format[field]) % value)
    elif isinstance(value, float) and field in self._float_format:
        value = self._unicode(("%%%sf" % self._float_format[field]) % value)
    return self._unicode(value)

def __getattr__(self, name):

    if name == "rowcount":
        return len(self._rows)
    elif name == "colcount":
        if self._field_names:
            return len(self._field_names)
        elif self._rows:
            return len(self._rows[0])
        else:
            return 0
    else:
        raise AttributeError(name)

def __getitem__(self, index):

    new = PrettyTable()
    new.field_names = self.field_names
    for attr in self._options:
        setattr(new, "_"+attr, getattr(self, "_"+attr))
    setattr(new, "_align", getattr(self, "_align"))
    if isinstance(index, slice):
        for row in self._rows[index]:
            new.add_row(row)
    elif isinstance(index, int):
        new.add_row(self._rows[index])
    else:
        raise Exception("Index %s is invalid, must be an integer or slice" % str(index))
    return new

def add_row(self, row):

    """Add a row to the table

    Arguments:

    row - row of data, should be a list with as many elements as the table
    has fields"""

    if self._field_names and len(row) != len(self._field_names):
        raise Exception("Row has incorrect number of values, (actual) %d!=%d (expected)" %(len(row),len(self._field_names)))
    if not self._field_names:
        self.field_names = [("Field %d" % (n+1)) for n in range(0,len(row))]
    self._rows.append(list(row))

def from_csv(fp, field_names = None, **kwargs):

    dialect = csv.Sniffer().sniff(fp.read(1024))
    fp.seek(0)
    reader = csv.reader(fp, dialect)

    table = PrettyTable(**kwargs)
    if field_names:
        table.field_names = field_names
    else:
        if py3k:
            table.field_names = [x.strip() for x in next(reader)]
        else:
            table.field_names = [x.strip() for x in reader.next()]

    for row in reader:
        table.add_row([x.strip() for x in row])

    return table

def from_db_cursor(cursor, **kwargs):

    if cursor.description:
        table = PrettyTable(**kwargs)
        table.field_names = [col[0] for col in cursor.description]
        for row in cursor.fetchall():
            table.add_row(row)
        return table

